CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', paytm_number text NOT NULL DEFAULT '', upi_id text NOT NULL DEFAULT '', preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id = (SELECT auth.uid()));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.payment_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, requires_user_auth boolean NOT NULL DEFAULT false, max_retries integer NOT NULL DEFAULT 2 CHECK (max_retries BETWEEN 0 AND 5), auto_email boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.payment_policies TO authenticated; GRANT ALL ON public.payment_policies TO service_role;
ALTER TABLE public.payment_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY policies_owner ON public.payment_policies FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TRIGGER policies_updated BEFORE UPDATE ON public.payment_policies FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.sync_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, counterparty text NOT NULL, counterparty_email text NOT NULL DEFAULT '', counterparty_address text NOT NULL, kind text NOT NULL DEFAULT 'Vendor', direction text NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), amount_type text NOT NULL CHECK (amount_type IN ('FIXED','VARIABLE')), amount numeric(14,2), max_cap numeric(14,2), policy_id uuid NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE','RETRYING_1_OF_2','FAILED','AWAITING_USER_AUTH')), last_at timestamptz, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(policy_id,user_id) REFERENCES public.payment_policies(id,user_id), CHECK ((amount_type = 'FIXED' AND amount > 0 AND max_cap IS NULL) OR (amount_type = 'VARIABLE' AND amount IS NULL AND (max_cap IS NULL OR max_cap > 0))));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.sync_requests TO authenticated; GRANT ALL ON public.sync_requests TO service_role;
ALTER TABLE public.sync_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY sync_owner ON public.sync_requests FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE FUNCTION public.validate_sync_draft() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN IF TG_OP = 'INSERT' AND NEW.status <> 'DRAFT' THEN RAISE EXCEPTION 'Payment connection required to activate a request'; END IF; IF TG_OP = 'UPDATE' AND (NEW.status IS DISTINCT FROM OLD.status OR NEW.last_at IS DISTINCT FROM OLD.last_at OR NEW.approved_at IS DISTINCT FROM OLD.approved_at) THEN RAISE EXCEPTION 'Only the payment service can change execution state'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER sync_validate BEFORE INSERT OR UPDATE ON public.sync_requests FOR EACH ROW EXECUTE FUNCTION public.validate_sync_draft();
CREATE TRIGGER sync_updated BEFORE UPDATE ON public.sync_requests FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, sync_request_id uuid REFERENCES public.sync_requests(id) ON DELETE SET NULL, order_id text NOT NULL UNIQUE, bank_ref text NOT NULL DEFAULT '', from_party text NOT NULL, to_party text NOT NULL, direction text NOT NULL CHECK (direction IN ('DEBIT','CREDIT')), source_type text NOT NULL CHECK (source_type IN ('SYNC_REQUEST','DIRECT_PAYMENT')), amount numeric(14,2) NOT NULL CHECK(amount > 0), status text NOT NULL CHECK (status IN ('SUCCESS','RETRYING','FAILED')), retry_count integer NOT NULL DEFAULT 0 CHECK (retry_count >= 0), bank_error text, is_automated boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT ON public.transactions TO authenticated; GRANT ALL ON public.transactions TO service_role;
ALTER TABLE public.transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY transactions_read ON public.transactions FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE TRIGGER transactions_updated BEFORE UPDATE ON public.transactions FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.transaction_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, transaction_id uuid NOT NULL, event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(transaction_id,user_id) REFERENCES public.transactions(id,user_id) ON DELETE CASCADE);
GRANT SELECT ON public.transaction_events TO authenticated; GRANT ALL ON public.transaction_events TO service_role;
ALTER TABLE public.transaction_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.transaction_events FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE TRIGGER events_updated BEFORE UPDATE ON public.transaction_events FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.knowledge_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, filename text NOT NULL, file_type text NOT NULL, storage_path text NOT NULL UNIQUE, size_bytes bigint NOT NULL CHECK(size_bytes > 0), status text NOT NULL DEFAULT 'UPLOADED' CHECK(status IN ('UPLOADED','PROCESSING','INDEXED','FAILED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.knowledge_documents TO authenticated; GRANT ALL ON public.knowledge_documents TO service_role;
ALTER TABLE public.knowledge_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY docs_read ON public.knowledge_documents FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE POLICY docs_create ON public.knowledge_documents FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND storage_path LIKE (auth.uid()::text || '/%') AND status = 'UPLOADED');
CREATE POLICY docs_delete ON public.knowledge_documents FOR DELETE TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE TRIGGER docs_updated BEFORE UPDATE ON public.knowledge_documents FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TABLE public.chat_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('user','ai')), text text NOT NULL CHECK (length(text) BETWEEN 1 AND 10000), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.chat_messages TO authenticated; GRANT ALL ON public.chat_messages TO service_role;
ALTER TABLE public.chat_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY chat_owner ON public.chat_messages FOR ALL TO authenticated USING (user_id = (SELECT auth.uid())) WITH CHECK (user_id = (SELECT auth.uid()));
CREATE TRIGGER chat_updated BEFORE UPDATE ON public.chat_messages FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE FUNCTION public.create_payiq_account() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id,name,phone,paytm_number,upi_id) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name',''),coalesce(NEW.raw_user_meta_data->>'phone',''),coalesce(NEW.raw_user_meta_data->>'paytm_number',''),coalesce(NEW.raw_user_meta_data->>'upi_id','')); INSERT INTO public.payment_policies(user_id,name,requires_user_auth,max_retries,auto_email) VALUES(NEW.id,'Standard Auto',false,2,true),(NEW.id,'Approve Before Debit',true,2,true); RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.create_payiq_account() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER payiq_account_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_payiq_account();
INSERT INTO public.profiles(id,name,phone,paytm_number,upi_id) SELECT id,coalesce(raw_user_meta_data->>'name',''),coalesce(raw_user_meta_data->>'phone',''),coalesce(raw_user_meta_data->>'paytm_number',''),coalesce(raw_user_meta_data->>'upi_id','') FROM auth.users ON CONFLICT(id) DO NOTHING;
INSERT INTO public.payment_policies(user_id,name,requires_user_auth,max_retries,auto_email) SELECT id,'Standard Auto',false,2,true FROM public.profiles UNION ALL SELECT id,'Approve Before Debit',true,2,true FROM public.profiles;
CREATE INDEX policies_owner_idx ON public.payment_policies(user_id);
CREATE INDEX sync_owner_idx ON public.sync_requests(user_id,created_at DESC);
CREATE INDEX transactions_owner_idx ON public.transactions(user_id,created_at DESC);
CREATE INDEX events_owner_idx ON public.transaction_events(user_id,transaction_id);
CREATE INDEX documents_owner_idx ON public.knowledge_documents(user_id,created_at DESC);
CREATE INDEX messages_owner_idx ON public.chat_messages(user_id,created_at);
CREATE POLICY payiq_files_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id = 'payiq-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
CREATE POLICY payiq_files_create ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id = 'payiq-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
CREATE POLICY payiq_files_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id = 'payiq-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);